            if (p.isBoulder) { spawnRockShatter(p.pos); spawnBoulderShrapnel(p.pos, BOULDER_SHRAPNEL_COUNT, p.vel.x > 0 ? 1 : -1); } if (p.isSludge) { p.health = 0; return false; } return false;
          }
        }
