    const shakeY = state.screenShakeTimer > 0 ? (Math.random() - 0.5) * 10 : 0;

    ctx.translate(-Math.floor(camera.x) + shakeX, -Math.floor(camera.y) + shakeY);

    // Draw Blocks
    blocks.forEach(b => {
      if (b.type === 'pit') return;
      ctx.fillStyle = stageColor ? stageColor.ground : '#444';
      if (b.type === 'door') ctx.fillStyle = '#333';
      if (b.type === 'platform') ctx.fillStyle = stageColor ? stageColor.accent : '#666';

      ctx.fillRect(b.x, b.y, b.w, b.h);

      if (b.type === 'door') {
         ctx.fillStyle = '#111';
         ctx.fillRect(b.x + 10, b.y + 10, b.w - 20, b.h - 20);
