    enemies.forEach(e => {
       if (e.type === 'boss') {
           BossLogic.drawBoss(ctx, e, stageId, frame);
           if (stageId === 'Drug Trade Dale') BossLogic.drawDaleDrugs(ctx, e);
       } else {
