           if (e.isBlownAway) {
               ctx.save();
               ctx.translate(e.pos.x + e.width/2, e.pos.y + e.height/2);
               ctx.rotate(e.rotation || 0);
               ctx.translate(-e.pos.x - e.width/2, -e.pos.y - e.height/2);
           }
           ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);

           if (e.enemyType === 'shield' && e.isShieldActive) {
               ctx.strokeStyle = '#00FFFF';
               ctx.lineWidth = 2;
               ctx.strokeRect(e.pos.x - 5, e.pos.y, 5, e.height);
           }
           if (e.isBlownAway) ctx.restore();
       }
    });

    // Draw Player
    if (player.invincibilityTimer % 4 < 2) {
       ctx.fillStyle = COLORS.MEATHEAD_SKIN;
       ctx.fillRect(player.pos.x, player.pos.y, player.width, player.height);
       ctx.fillStyle = COLORS.MEATHEAD_PANTS;
       ctx.fillRect(player.pos.x, player.pos.y + player.height * 0.6, player.width, player.height * 0.4);

       ctx.fillStyle = '#000';
       const eyeX = player.facing === 1 ? player.pos.x + player.width - 10 : player.pos.x + 2;
       ctx.fillRect(eyeX, player.pos.y + 10, 8, 4);

       if (player.currentWeapon !== 'GUN') {
           ctx.fillStyle = COLORS.GUN;
           const gunX = player.facing === 1 ? player.pos.x + player.width - 5 : player.pos.x - 10;
           ctx.fillRect(gunX, player.pos.y + 30, 15, 8);
       }

       if (player.filthShieldTimer && player.filthShieldTimer > 0) {
           ctx.strokeStyle = '#ADFF2F';
           ctx.lineWidth = 3;
           ctx.beginPath();
           ctx.arc(player.pos.x + player.width/2, player.pos.y + player.height/2, Math.max(player.width, player.height), 0, Math.PI * 2);
           ctx.stroke();
           ctx.fillStyle = 'rgba(173, 255, 47, 0.2)';
           ctx.fill();
       }
    }

    // Draw Projectiles
    projectiles.forEach(p => {
       ctx.save();
       ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2);
       if (p.rotation) ctx.rotate(p.rotation);
       ctx.translate(-p.pos.x - p.width/2, -p.pos.y - p.height/2);

       if (p.isBoulder) {
           ctx.fillStyle = '#5D4037';
           ctx.beginPath(); ctx.arc(p.pos.x + p.width/2, p.pos.y + p.height/2, p.width/2, 0, Math.PI*2); ctx.fill();
       } else if (p.isIce) {
           ctx.fillStyle = COLORS.PROJECTILE_ICE;
           ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
       } else if (p.isSludge) {
           ctx.fillStyle = '#ADFF2F';
           ctx.beginPath(); ctx.arc(p.pos.x + p.width/2, p.pos.y + p.height/2, p.width/2, 0, Math.PI*2); ctx.fill();
       } else if (p.isMethBarrel) {
           ctx.fillStyle = '#111';
           ctx.strokeStyle = '#FFD700';
           ctx.lineWidth = 2;
           ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
           ctx.strokeRect(p.pos.x, p.pos.y, p.width, p.height);
       } else if (p.isPoop) {
           ctx.fillStyle = '#5D4037';
           ctx.beginPath(); ctx.ellipse(p.pos.x + p.width/2, p.pos.y + p.height/2, p.width/2, p.height/2, 0, 0, Math.PI*2); ctx.fill();
       } else {
           ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY;
           ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
       }
       ctx.restore();
    });

    // Draw Damage Numbers
    damageNumbers.forEach(d => {
        ctx.save();
        ctx.globalAlpha = d.life / d.maxLife;
        ctx.font = `bold ${d.isCritical ? '24px' : '16px'} "Press Start 2P", monospace`; 
        ctx.fillStyle = d.isCritical ? '#FFD700' : (d.value > 50 ? '#FF4500' : '#FFFFFF');
        ctx.textAlign = 'center';
        ctx.shadowColor = 'black';
        ctx.shadowBlur = 4;
        ctx.fillText(d.value.toString(), d.pos.x, d.pos.y);
        ctx.restore();
    });

    ctx.restore(); 

    if (state.playerLastVulgarity) {
        const pScreenX = player.pos.x - camera.x + player.width/2;
        const pScreenY = player.pos.y - camera.y - 20;
        ctx.font = 'bold 12px monospace';
        ctx.fillStyle = 'white';
        ctx.textAlign = 'center';
        ctx.fillText(state.playerLastVulgarity, pScreenX, pScreenY);
    }
    if (state.bossLastVulgarity) {
        const boss = enemies.find(e => e.type === 'boss');
        if (boss) {
            const bScreenX = boss.pos.x - camera.x + boss.width/2;
            const bScreenY = boss.pos.y - camera.y - 20;
            ctx.font = 'bold 14px monospace';
            ctx.fillStyle = 'red';
            ctx.textAlign = 'center';
            ctx.fillText(state.bossLastVulgarity, bScreenX, bScreenY);
        }
    }

    if (state.victoryString && (status === GameStatus.PLAYING || status === GameStatus.VICTORY || status === GameStatus.BOSS_VICTORY_SPEECH)) {
        ctx.save();
        ctx.font = 'bold 50px "Press Start 2P", monospace';
        ctx.fillStyle = 'yellow';
        ctx.textAlign = 'center';
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 4;
        ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        ctx.restore();
    }

    if (state.deathTimer > 0) {
        ctx.save();
        ctx.font = 'bold 60px "Press Start 2P", monospace';
        ctx.fillStyle = '#FF0000';
        ctx.textAlign = 'center';
        ctx.fillText(state.deathString || "DEAD", CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
