             <div onClick={onCheatAllWeapons} className="cursor-pointer hover:text-white">CHEAT WEAPONS: {cheatEnabled ? 'ON' : 'OFF'}</div>
             <div onClick={onToggleInvincibility} className="cursor-pointer hover:text-white">INVINCIBILITY: {invincibilityEnabled ? 'ON' : 'OFF'}</div>
             <div onClick={onToggleInfiniteAmmo} className="cursor-pointer hover:text-white">INF AMMO: {infiniteAmmoEnabled ? 'ON' : 'OFF'}</div>
             <div onClick={onToggleInfinitePower} className="cursor-pointer hover:text-white">INF POWER: {infinitePowerEnabled ? 'ON' : 'OFF'}</div>
             <div onClick={onToggleJumpToBoss} className="cursor-pointer hover:text-white">BOSS RUSH: {jumpToBossEnabled ? 'ON' : 'OFF'}</div>
             <div className="flex gap-2">
                RANK: {progressionRank} 
                <button onClick={onDecrementRank}>[-]</button>
                <button onClick={onIncrementRank}>[+]</button>
             </div>
          </div>
        )}
        <ControlsGuide />
      </div>
    );
  }

  if (status === GameStatus.STAGE_SELECT) {
    const stages = STAGES(progressionRank);
    return (
      <div className="absolute inset-0 z-20 bg-black p-8 flex flex-col">
        <h2 className="text-2xl text-white font-bold mb-8 text-center uppercase tracking-widest border-b-2 border-red-600 pb-2">Select Target</h2>
        <div className="grid grid-cols-2 gap-4 flex-1">
           {stages.map((stage, i) => {
             const isDefeated = defeatedStages.includes(stage.id);
             const isSelected = i === selectedIndex;
             return (
               <div 
                 key={stage.id}
                 onClick={() => !isDefeated && onSelectStage(stage.id)}
                 className={`
                   relative border-4 p-4 flex flex-col items-center justify-center cursor-pointer transition-all
                   ${isSelected ? 'border-white scale-105 z-10 bg-gray-900' : 'border-gray-800 bg-black grayscale opacity-50'}
                   ${isDefeated ? 'opacity-30 pointer-events-none' : ''}
                 `}
               >
                 {isDefeated && <div className="absolute inset-0 flex items-center justify-center text-red-600 font-black text-4xl transform -rotate-12 z-20">DEAD</div>}
                 <div className={`w-16 h-16 mb-2 ${stage.color} rounded-full border-2 border-white`} />
                 <div className="text-white font-bold text-xs uppercase text-center">{stage.id}</div>
                 <div className="text-gray-500 text-[8px] font-mono mt-1 text-center">{WEAPON_NAMES[stage.id]}</div>
               </div>
             );
           })}
        </div>
      </div>
    );
  }

  if (status === GameStatus.LEVEL_INTRO || status === GameStatus.BOSS_TRANSITION) {
    return (
      <div className="absolute inset-0 z-20 bg-black flex flex-col items-center justify-center">
        <div className="text-4xl font-black text-white mb-2 uppercase tracking-widest">{status === GameStatus.BOSS_TRANSITION ? "WARNING" : "GET READY"}</div>
        <div className="w-16 h-2 bg-red-600 animate-pulse" />
      </div>
    );
  }

  if (status === GameStatus.BOSS_INTRO) {
    return (
      <div className="absolute inset-0 z-20 bg-black/90 flex flex-col items-center justify-center p-12 text-center">
        <h2 className="text-4xl text-red-600 font-black uppercase mb-4 tracking-tighter" style={{ textShadow: '2px 2px 0px white' }}>{stageId}</h2>
        <div className="text-white text-xl italic font-serif mb-8 max-w-lg leading-relaxed">"{bossTaunt}"</div>
        <div className={`text-gray-500 text-sm font-mono animate-pulse ${isTransitioning ? 'opacity-0' : 'opacity-100'}`}>PRESS START</div>
      </div>
    );
  }

  if (status === GameStatus.BOSS_VICTORY_SPEECH) {
    const rewardWeapon = stageId ? WEAPON_NAMES[stageId] : "UNKNOWN";
    const desc = stageId ? WEAPON_DESCRIPTIONS[stageId] : "";

    return (
      <div className="absolute inset-0 z-20 bg-blue-900 flex flex-col items-center justify-center p-12 text-center border-8 border-white">
        <h2 className="text-4xl text-white font-black uppercase mb-2">TARGET DESTROYED</h2>
        <div className="text-yellow-400 text-lg font-bold mb-8">{victorySpeech}</div>

        <div className="bg-black/50 p-6 border-2 border-white max-w-md">
           <div className="text-white text-xs font-bold uppercase mb-2 text-gray-400">WEAPON ACQUIRED</div>
           <div className="text-2xl text-white font-black uppercase mb-2 text-red-500">{rewardWeapon}</div>
           <div className="text-white text-sm leading-tight font-mono">{desc}</div>
        </div>

        <div className={`mt-8 text-white text-sm font-bold animate-pulse ${isTransitioning ? 'opacity-0' : 'opacity-100'}`}>PRESS START</div>
      </div>
    );
  }

  if (status === GameStatus.PAUSED) {
    return (
      <div className="absolute inset-0 z-30 bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center">
        <h2 className="text-6xl font-black text-white italic mb-8 tracking-tighter transform -skew-x-12">PAUSED</h2>

        <div className="grid grid-cols-4 gap-4 mb-8">
          {availableWeapons.map((w, i) => {
            const isSelected = i === selectedIndex;
            const isEquipped = w === currentWeapon;
            return (
              <div 
                key={w} 
                className={`
                  w-16 h-16 border-2 flex items-center justify-center cursor-pointer relative
                  ${isSelected ? 'border-red-500 bg-white/10 scale-110' : 'border-gray-600 bg-black'}
                  ${isEquipped ? 'ring-2 ring-yellow-400' : ''}
                `}
                onClick={() => onIconClick(i)}
              >
                <span className="text-[10px] text-white font-bold">{w.substring(0, 3)}</span>
              </div>
            );
          })}
        </div>

        <div className="flex flex-col gap-4 w-64">
           <button 
             className={`px-6 py-2 border-2 font-bold uppercase ${selectedIndex === availableWeapons.length ? 'bg-white text-black border-white' : 'text-white border-gray-600 hover:border-white'}`}
             onMouseEnter={() => onIconClick(availableWeapons.length)}
             onClick={onResume}
           >
             Resume Game
           </button>
           <button 
             className={`px-6 py-2 border-2 font-bold uppercase ${selectedIndex === availableWeapons.length + 1 ? 'bg-white text-black border-white' : 'text-white border-gray-600 hover:border-white'}`}
             onMouseEnter={() => onIconClick(availableWeapons.length + 1)}
             onClick={onBossSelect}
           >
             Stage Select
           </button>
           <button 
             className={`px-6 py-2 border-2 font-bold uppercase ${selectedIndex === availableWeapons.length + 2 ? 'bg-white text-black border-white' : 'text-white border-gray-600 hover:border-white'}`}
             onMouseEnter={() => onIconClick(availableWeapons.length + 2)}
             onClick={onQuitToMenu}
           >
             Quit to Title
           </button>
        </div>
      </div>
    );
  }

  if (status === GameStatus.GAME_OVER) {
    return (
      <div className="absolute inset-0 z-20 bg-red-900/90 flex flex-col items-center justify-center">
        <h2 className="text-6xl font-black text-black mb-4">YOU DIED</h2>
        <div className={`text-white text-xl font-bold animate-pulse ${isTransitioning ? 'opacity-0' : 'opacity-100'}`}>PRESS START TO RETRY</div>
      </div>
    );
  }

  if (status === GameStatus.VICTORY) {
    return (
      <div className="absolute inset-0 z-20 bg-white flex flex-col items-center justify-center text-center p-12">
        <h2 className="text-6xl font-black text-black mb-8">MISSION ACCOMPLISHED</h2>
        <div className="text-black text-xl font-bold max-w-xl mb-12">
          ALL TARGETS ELIMINATED. THE GYM IS SAFE. FOR NOW.
        </div>
        <div className={`text-black text-sm font-mono animate-pulse ${isTransitioning ? 'opacity-0' : 'opacity-100'}`}>PRESS START</div>
      </div>
    );
  }

  return null;
};

export default Overlay;

import React, { useEffect, useRef } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, DamageNumber, 
  Pickup, Volcano, WeaponType, Entity, Vector2
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, GRAVITY, FPS_TICK, 
  INITIAL_PLAYER_HEALTH, PLAYER_SPEED, PLAYER_JUMP_FORCE, 
  PLAYER_INVINCIBILITY_FRAMES, MAX_AMMO, 
  STAGES, BOSS_DOOR_X, FRICTION_DEFAULT,
  COLORS, PARTICLE_PALETTES,
  CHARGE_SPEED, UPPERCUT_FORCE, UPPERCUT_AIR_SPEED,
  MAX_SPECIAL_CHARGES, SPECIAL_CHARGE_REGEN_FRAMES,
  CHARGE_DURATION, PLAYER_PUSHBACK_VEL_X, PLAYER_PUSHBACK_VEL_Y,
  PLAYER_PUSHBACK_DURATION, VULGARITY_TEXT_DURATION, 
  SCREEN_SHAKE_MAX, DOOR_WIDTH, DOOR_OPEN_SPEED,
  BOSS_CHARGE_DAMAGE, BOSS_UPPERCUT_DAMAGE
} from '../constants';
import * as BossLogic from '../boss';
import * as WeaponLogic from '../weapons';

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, specialCharges: number, specialChargeTimer: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => void;
  onBossEncounter: () => void;
  onBossTransition: () => void;
  onBossDefeated: (stageId: string) => void;
  onBossDeath: () => void;
  onBossSelect: () => void;
  onGameOver: (victory: boolean) => void;
  onIntroComplete: () => void;
  onTogglePause: () => void;
  currentWeapon: WeaponType;
  initialAmmo: Record<WeaponType, number>;
  invincibilityEnabled: boolean;
  infiniteAmmoEnabled: boolean;
  infinitePowerEnabled: boolean;
  jumpToBossEnabled: boolean;
  bossTauntText: string;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  status, stageId, onPlayerUpdate, onBossEncounter, onBossTransition, 
  onBossDefeated, onBossDeath, onBossSelect, onGameOver, onIntroComplete,
  onTogglePause, currentWeapon, initialAmmo,
  invincibilityEnabled, infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const keys = useRef<Record<string, boolean>>({});

  const state = useRef({
    player: {
      id: 'player', pos: { x: 100, y: 300 }, vel: { x: 0, y: 0 },
      width: 32, height: 64, health: INITIAL_PLAYER_HEALTH, maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player' as const, isCharging: false, isUppercutting: false, isDucking: false,
      specialCharges: 2, specialChargeTimer: 0, chargeDuration: 0,
      isJumping: false, isGrounded: false, facing: 1 as 1 | -1,
      shootCooldown: 0, jumpPrepTimer: 0, landTimer: 0, invincibilityTimer: 0,
      pushbackTimer: 0, killSatisfactionTimer: 0, bossKillSatisfactionTimer: 0,
      hasUsedAirMove: false, jumpInputReleased: true, chargeInputReleased: true,
      currentWeapon: 'GUN' as WeaponType, availableWeapons: ['GUN'] as WeaponType[],
      weaponAmmo: { ...initialAmmo }
    } as Player,
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    particles: [] as Particle[],
    damageNumbers: [] as DamageNumber[],
    pickups: [] as Pickup[],
    camera: { x: 0, y: 0 },
    blocks: [] as { x: number, y: number, w: number, h: number, type: 'ground' | 'wall' | 'platform' }[],
    bgElements: [] as { x: number, y: number, type: string, speed: number }[],

    // Logic Timers
    frame: 0,
    stageId: stageId,
    screenShake: 0,
    bossDoorState: 'closed' as 'closed' | 'opening' | 'open',
    bossDoorY: 0,
    bossEncountered: false,
    bossDefeated: false,
    arenaLocked: false,

    // Boss Logic Specifics
    bossVolcanoes: [] as Volcano[],
    bossVolcanoTelegraphs: [] as Volcano[],
    bossPoopTelegraphs: [] as any[],
    bossSteamExplosions: [] as any[],
    ernieVibrationTimer: 0,
    victorWallSide: 0,
    tsunamiActive: false,
    tsunamiX: 0,
    tsunamiDir: 1,
    tsunamiStartX: 0,

    // Victory/Death State
    bossExplosionTimer: 0,
    bossExplosionPos: { x: 0, y: 0 },
    victoryString: "",
    postVictoryTimer: 0,
    playerStunTimer: 0,
    vulgarityText: "",
    vulgarityTimer: 0,
  }).current;

  // Sync prop changes to mutable state
  useEffect(() => {
    state.player.currentWeapon = currentWeapon;
    state.player.weaponAmmo = { ...initialAmmo };
  }, [currentWeapon, initialAmmo]);

  useEffect(() => {
    const initLevel = () => {
      state.player.pos = { x: 100, y: 400 };
      state.player.vel = { x: 0, y: 0 };
      state.player.health = INITIAL_PLAYER_HEALTH;
      state.player.specialCharges = 2;
      state.player.weaponAmmo = { ...initialAmmo };
      state.enemies = [];
      state.projectiles = [];
      state.particles = [];
      state.damageNumbers = [];
      state.pickups = [];
      state.camera = { x: 0, y: 0 };
      state.bossEncountered = false;
      state.bossDefeated = false;
      state.arenaLocked = false;
      state.bossDoorState = 'closed';
      state.bossDoorY = 0;
      state.bossExplosionTimer = 0;
      state.victoryString = "";
      state.postVictoryTimer = 0;
      state.playerStunTimer = 0;
      state.tsunamiActive = false;

      // Generate Level Blocks
      state.blocks = [];
      // Ground floor
      for (let x = -200; x < 9000; x += 100) {
        state.blocks.push({ x, y: 550, w: 100, h: 50, type: 'ground' });
      }
      // Boss Arena Walls
      state.blocks.push({ x: BOSS_DOOR_X - 50, y: 0, w: 50, h: 600, type: 'wall' }); // Left Wall (Door)
      state.blocks.push({ x: 8000, y: 0, w: 50, h: 600, type: 'wall' }); // Right Wall

      // Random Platforms
      for (let x = 600; x < BOSS_DOOR_X - 500; x += 400 + Math.random() * 300) {
        const y = 350 + Math.random() * 100;
        state.blocks.push({ x, y, w: 200, h: 20, type: 'platform' });
        // Maybe an enemy on platform
        if (Math.random() > 0.5) {
           const type = Math.random() > 0.5 ? 'drone' : 'turret';
           state.enemies.push({
             id: `e-${x}`, pos: { x: x + 80, y: y - 50 }, vel: { x: 0, y: 0 },
             width: 40, height: 40, health: 30, maxHealth: 30, type: 'enemy',
             enemyType: type, behavior: 'patrol', patrolRange: 100, initialX: x + 80, shootTimer: 60
           });
        }
      }

      // BG Elements
      state.bgElements = [];
      for(let i=0; i<30; i++) {
        state.bgElements.push({
          x: Math.random() * 8000, y: Math.random() * 400,
          type: Math.random() > 0.8 ? 'cloud_big' : 'cloud_small',
          speed: 0.2 + Math.random() * 0.5
        });
      }

      // Jump to boss cheat
      if (jumpToBossEnabled) {
        state.player.pos.x = BOSS_DOOR_X - 200;
        state.camera.x = BOSS_DOOR_X - 600;
      }
    };

    if (status === GameStatus.LEVEL_INTRO) {
      initLevel();
      setTimeout(onIntroComplete, 2000);
    }
  }, [status, stageId, jumpToBossEnabled]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keys.current[e.key.toLowerCase()] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => { 
      window.removeEventListener('keydown', handleKeyDown); 
      window.removeEventListener('keyup', handleKeyUp); 
    };
  }, []);

  // Main Game Loop
  useEffect(() => {
    const loop = () => {
      if (status === GameStatus.PLAYING || status === GameStatus.BOSS_TRANSITION || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH) {
        update();
        draw();
      }
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  });

  const update = () => {
    if (status !== GameStatus.PLAYING && status !== GameStatus.BOSS_TRANSITION) return;

    state.frame++;
    if (state.screenShake > 0) state.screenShake--;
    if (state.playerStunTimer > 0) state.playerStunTimer--;
    if (state.vulgarityTimer > 0) state.vulgarityTimer--;

    // Helper Implementations
    const helpers: BossLogic.BossHelpers & WeaponLogic.WeaponHelpers = {
       addProjectile: (p) => state.projectiles.push(p),
       addParticle: (p) => state.particles.push(p),
       spawnDamageNumber: (pos, val, crit) => state.damageNumbers.push({ 
         id: `dn-${Date.now()}-${Math.random()}`, value: val, pos: { ...pos }, vel: { x: (Math.random()-0.5)*2, y: -2 }, life: 60, maxLife: 60, isCritical: !!crit 
       }),
       spawnExplosion: (pos, color, count, baseVelX = 0, spread = 5) => {
         for(let i=0; i<count; i++) state.particles.push({
           pos: { ...pos }, vel: { x: baseVelX + (Math.random()-0.5)*spread, y: (Math.random()-0.5)*spread },
           life: 20+Math.random()*20, color, size: 4+Math.random()*4
         });
       },
       spawnGlassShatter: (pos) => {
         for(let i=0; i<10; i++) state.particles.push({
           pos: { ...pos }, vel: { x: (Math.random()-0.5)*10, y: (Math.random()-0.5)*10 },
           life: 40, color: '#AEEEEE', size: 3, isGlass: true
         });
       },
       setScreenShake: (dur) => state.screenShake = dur,
       playGunSound: () => {}, // Placeholder for audio
       triggerBossDeath: (boss, facing, wasWeakness) => BossLogic.triggerBossDeath(boss, facing, wasWeakness, stageId, state.player.currentWeapon, state, helpers),
       spawnDeathShower: (pos, facing, multiplier = 1, isBoss = false) => {
          const colors = isBoss ? PARTICLE_PALETTES.GORE : PARTICLE_PALETTES.FLESH;
          for(let i=0; i<20*multiplier; i++) state.particles.push({
            pos: { ...pos }, vel: { x: facing * (5 + Math.random()*15), y: -5 - Math.random()*15 },
            life: 60 + Math.random()*60, color: colors[Math.floor(Math.random()*colors.length)], size: 4+Math.random()*6, isBossGore: isBoss
          });
       },
       onBossDeath: () => {
         state.bossDefeated = true;
         onBossDefeated(stageId!);
         setTimeout(onBossDeath, 4000); // Trigger victory speech UI after delay
       },
       speakVulgarity: (cat) => { /* Handle speech/text vulgarity */ },
       spawnSteamExplosionParticles: (pos, count=10) => {
         for(let i=0; i<count; i++) state.particles.push({
           pos: { ...pos }, vel: { x: (Math.random()-0.5)*4, y: -2-Math.random()*4 },
           life: 60, color: 'rgba(255,255,255,0.5)', size: 10
         });
       },
       spawnPoopExplosion: (pos, count=10) => { /* ... */ },
       spawnPowderExplosion: (pos, count=10) => { /* ... */ },
       spawnMethExplosion: (pos, count=10) => { /* ... */ },
       setBossVulgarity: (text, dur) => { state.vulgarityText = text; state.vulgarityTimer = dur; },
       setErnieVibration: (dur) => state.ernieVibrationTimer = dur,
       setPlayerStun: (dur) => state.playerStunTimer = dur,
       addVolcano: (v) => state.bossVolcanoes.push(v),
       clearVolcanoes: () => state.bossVolcanoes = [],
       addVolcanoTelegraph: (v) => state.bossVolcanoTelegraphs.push(v),
       clearVolcanoTelegraphs: () => state.bossVolcanoTelegraphs = [],
       addPoopTelegraph: (t) => state.bossPoopTelegraphs.push(t),
       clearPoopTelegraphs: () => state.bossPoopTelegraphs = [],
       setVictorWallSide: (s) => state.victorWallSide = s,
       setTsunamiActive: (a) => state.tsunamiActive = a
    };

    const player = state.player;

    // -- INPUT HANDLING --
    const gamepads = navigator.getGamepads();
    const gp = gamepads[0];
    let padMoveX = 0, padMoveY = 0, padJump = false, padSpecial = false, padShoot = false;

    if (gp) {
      const DEADZONE = 0.2;
      if (Math.abs(gp.axes[0]) > DEADZONE) padMoveX = gp.axes[0];
      if (Math.abs(gp.axes[1]) > DEADZONE) padMoveY = gp.axes[1];
      if (gp.buttons[14]?.pressed) padMoveX = -1; 
      if (gp.buttons[15]?.pressed) padMoveX = 1;  
      if (gp.buttons[12]?.pressed) padMoveY = -1; 
      if (gp.buttons[13]?.pressed) padMoveY = 1;  
      padJump = gp.buttons[0]?.pressed; 
      padShoot = gp.buttons[2]?.pressed || gp.buttons[3]?.pressed; 
      padSpecial = gp.buttons[1]?.pressed; 
    }

    const km = keys.current, isStunned = state.playerStunTimer > 0, hasAmmo = (wpn: WeaponType) => wpn === 'GUN' || player.weaponAmmo[wpn] >= 1;

    // Player Physics & Logic (Simplified for brevity, assuming full implementation follows Meathead physics)
    if (!isStunned && player.health > 0 && status === GameStatus.PLAYING) {
        // Horizontal Movement
        let moveDir = 0;
        if (km['arrowleft'] || km['a'] || padMoveX < -0.3) moveDir = -1;
        if (km['arrowright'] || km['d'] || padMoveX > 0.3) moveDir = 1;

        player.vel.x = moveDir * PLAYER_SPEED;
        if (moveDir !== 0) player.facing = moveDir as 1 | -1;

        // Jump
        const jumpPressed = km[' '] || km['arrowup'] || km['w'] || padJump;
        if (jumpPressed && !player.isJumping && player.isGrounded && player.jumpInputReleased) {
            player.vel.y = PLAYER_JUMP_FORCE;
            player.isJumping = true;
            player.isGrounded = false;
            player.jumpInputReleased = false;
        }
        if (!jumpPressed) player.jumpInputReleased = true;

        // Shooting
        const shootPressed = km['f'] || km['z'] || padShoot; // Assuming F or Z or Pad
        // Mouse click is usually handled via event listener updating a ref, skipping for now in favor of keys
        if (shootPressed && player.shootCooldown <= 0 && hasAmmo(player.currentWeapon)) {
            WeaponLogic.fireWeapon(player, state, helpers, (km['arrowup'] || km['w'] || padMoveY < -0.3), (km['arrowdown'] || km['s'] || padMoveY > 0.3), infiniteAmmoEnabled);
        }
    }

    // Apply Physics
    if (player.pushbackTimer > 0) player.pushbackTimer--;
    else player.vel.x *= FRICTION_DEFAULT;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    // Collision with World
    let onGround = false;
    // Floor
    if (player.pos.y > 480) { player.pos.y = 480; player.vel.y = 0; onGround = true; player.isJumping = false; }

    // Platforms & Walls
    state.blocks.forEach(b => {
        if (b.type === 'ground' || b.type === 'platform') {
            if (player.pos.x + player.width > b.x && player.pos.x < b.x + b.w && 
                player.pos.y + player.height >= b.y && player.pos.y + player.height <= b.y + 20 && player.vel.y >= 0) {
                player.pos.y = b.y - player.height; player.vel.y = 0; onGround = true; player.isJumping = false;
            }
        }
        if (b.type === 'wall') {
            if (player.pos.y + player.height > b.y && player.pos.y < b.y + b.h) {
                if (player.vel.x > 0 && player.pos.x + player.width > b.x && player.pos.x < b.x + 20) player.pos.x = b.x - player.width;
                if (player.vel.x < 0 && player.pos.x < b.x + b.w && player.pos.x > b.x + b.w - 20) player.pos.x = b.x + b.w;
            }
        }
    });
