    // Cooldowns
    if (player.shootCooldown > 0) player.shootCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;
    if (state.playerStunTimer > 0) state.playerStunTimer--;

    // Camera Follow
    let targetCamX = player.pos.x - CANVAS_WIDTH / 2 + player.width / 2;
    // Lock Camera at Boss Door if encountered
    if (state.arenaLocked) targetCamX = BOSS_DOOR_X - 50; 
    else targetCamX = Math.max(0, Math.min(BOSS_DOOR_X - 50, targetCamX));

    state.camera.x += (targetCamX - state.camera.x) * 0.1;

    // Boss Transition Logic
    if (player.pos.x > BOSS_DOOR_X - 100 && !state.bossEncountered) {
        onBossTransition();
        state.arenaLocked = true;
        state.bossDoorState = 'opening';
    }
    if (state.bossDoorState === 'opening') {
        state.bossDoorY += DOOR_OPEN_SPEED;
        if (state.bossDoorY >= 150) { 
            state.bossDoorState = 'open'; 
            state.bossEncountered = true;
            onBossEncounter();
