            state.enemies.push({
                id: stageId || 'boss', pos: { x: BOSS_DOOR_X + 400, y: 300 }, vel: { x: 0, y: 0 },
                width: 80, height: 80, health: 3000, maxHealth: 3000, type: 'boss',
                enemyType: 'drone', behavior: 'patrol', patrolRange: 0, initialX: 0, shootTimer: 0,
                bossState: 'idle', stateTimer: 60
