    state.enemies.forEach(e => {
        if (e.type === 'boss') {
            BossLogic.updateBossAI(e, stageId, player, player.currentWeapon, invincibilityEnabled, state, helpers);
        }
        // Simple Enemy Logic
        else {
             e.pos.x += e.vel.x; e.pos.y += e.vel.y;
