    }

    // Check Death
    if (player.health <= 0 && status === GameStatus.PLAYING) {
        onGameOver(false);
    }
  };

  const draw = () => {
    const ctx = canvasRef.current?.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save();

    // Screen Shake
    if (state.screenShake > 0) {
        const dx = (Math.random() - 0.5) * state.screenShake;
        const dy = (Math.random() - 0.5) * state.screenShake;
        ctx.translate(dx, dy);
    }

    // Camera Transform
    ctx.translate(-state.camera.x, -state.camera.y);

    // Draw BG
    ctx.fillStyle = COLORS.BG_LIGHT;
    ctx.fillRect(state.camera.x, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    state.bgElements.forEach(bg => {
        ctx.fillStyle = '#2C3E50';
        ctx.fillRect(bg.x, bg.y, bg.type === 'cloud_big' ? 100 : 50, 30);
    });

    // Draw Blocks
    ctx.fillStyle = COLORS.GROUND;
    state.blocks.forEach(b => ctx.fillRect(b.x, b.y, b.w, b.h));

    // Draw Door
    const doorH = 600;
    ctx.fillStyle = '#444';
    ctx.fillRect(BOSS_DOOR_X - 50, 0 - state.bossDoorY, 40, doorH);

    // Draw Player
    if (state.player.health > 0) {
        if (state.player.invincibilityTimer % 4 < 2) {
             ctx.fillStyle = COLORS.MEATHEAD_SKIN;
             ctx.fillRect(state.player.pos.x, state.player.pos.y, state.player.width, state.player.height);
             // Gun
             ctx.fillStyle = COLORS.GUN;
             const gunX = state.player.facing === 1 ? state.player.pos.x + 20 : state.player.pos.x - 10;
             ctx.fillRect(gunX, state.player.pos.y + 20, 20, 10);
        }
    }

    // Draw Enemies
    state.enemies.forEach(e => {
        if (e.type === 'boss') BossLogic.drawBoss(ctx, e, stageId, state.frame);
        else {
             ctx.fillStyle = COLORS.ENEMY_DRONE;
             ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
        }
    });

    // Draw Projectiles
    state.projectiles.forEach(p => {
        ctx.fillStyle = p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY;
        if (p.isBoulder) ctx.fillStyle = '#5D4037';
        if (p.isIce) ctx.fillStyle = '#AEEEEE';
        ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height);
    });

    // Draw Particles
    state.particles.forEach(p => {
        ctx.fillStyle = p.color;
        ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size);
        p.pos.x += p.vel.x; p.pos.y += p.vel.y;
        p.life--;
    });
    // Clean dead particles
    state.particles = state.particles.filter(p => p.life > 0);

    // Draw Damage Numbers
    state.damageNumbers.forEach(dn => {
        ctx.fillStyle = dn.isCritical ? '#FFD700' : '#FFF';
        ctx.font = dn.isCritical ? 'bold 20px sans-serif' : '14px sans-serif';
        ctx.fillText(Math.floor(dn.value).toString(), dn.pos.x, dn.pos.y);
        dn.pos.y += dn.vel.y; dn.life--;
    });
    state.damageNumbers = state.damageNumbers.filter(d => d.life > 0);

    ctx.restore();
  };

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="block" />;
};

