}

export const getBossDamage = (boss: Enemy, stageId: string | null, weapon: WeaponType, projectile?: Projectile): number => {
  let damage = 10; // Default
  const isWeakness = checkIsWeakness(stageId, weapon, projectile);

  if (weapon === 'GUN') damage = BULLET_DAMAGE;
  else if (weapon === 'BOULDER') damage = 25; // Resisted by default unless weak
  else if (weapon === 'SHOTGUN') damage = 15;
  else if (weapon === 'FLAMETHROWER') damage = 4; // Per tick
  else if (weapon === 'TSUNAMI') damage = TSUNAMI_DAMAGE_BOSS;
  else if (weapon === 'NEEDLES') damage = 5;
  else if (weapon === 'TASER') damage = 2; // Resisted
  else if (weapon === 'SLUDGE') damage = 10;

  if (isWeakness) {
    if (weapon === 'TSUNAMI') return TSUNAMI_DAMAGE_WEAKNESS;
    return WEAKNESS_DAMAGE; 
  }

  // Specific resistances
  if (stageId === 'Blackout Barry' && weapon === 'TASER') return 0; // Heal? Or immune.
  if (stageId === 'Victor Volcano' && weapon === 'FLAMETHROWER') return 0;
  if (stageId === 'Artie Avalanche' && weapon === 'SHOTGUN') return 0;

  if (projectile && projectile.damage) return projectile.damage;

  return damage;
};

export const checkIsWeakness = (stageId: string | null, weapon: WeaponType, projectile?: Projectile): boolean => {
  if (!stageId) return false;

  // Cycle mappings
  if (stageId === 'Artie Avalanche' && (weapon === 'FLAMETHROWER' || weapon === 'BOULDER')) return true;
  if (stageId === 'Victor Volcano' && (weapon === 'TSUNAMI' || weapon === 'SHOTGUN')) return true;
  if (stageId === 'Ernie Earthquake' && (weapon === 'NEEDLES' || weapon === 'SLUDGE')) return true;
  if (stageId === 'Hector Hurricane' && (weapon === 'TASER' || weapon === 'SHOTGUN')) return true;
  if (stageId === 'Toxic Tommy' && (weapon === 'FLAMETHROWER')) return true;
  if (stageId === 'Blackout Barry' && (weapon === 'BOULDER')) return true;
  if (stageId === 'Oily Oscar' && (weapon === 'FLAMETHROWER')) return true;
  if (stageId === 'Drug Trade Dale' && (weapon === 'TASER')) return true;

  return false;
};

