  if (status === GameStatus.PAUSED) {
     return (
       <div className="absolute inset-0 bg-black/90 z-50 flex flex-row p-8 gap-8 items-start justify-center">
          {/* Weapon Grid */}
          <div className="w-2/3">
             <h3 className="text-white font-black italic text-2xl mb-4 border-b-2 border-white pb-2">ARSENAL</h3>
             <div className="grid grid-cols-4 gap-2">
                {ALL_WEAPONS_SET_0.map((w, idx) => {
                   const hasWeapon = props.availableWeapons.includes(w);
                   const isSelected = props.selectedIndex === idx && props.selectedIndex < ALL_WEAPONS_SET_0.length;
                   const isEquipped = props.currentWeapon === w;

                   return (
                     <div 
                        key={w} 
                        className={`
                          aspect-square border-2 flex flex-col items-center justify-center relative p-1
                          ${hasWeapon ? (isSelected ? 'border-yellow-400 bg-gray-800' : 'border-gray-600 bg-gray-900') : 'border-gray-800 bg-black opacity-30'}
                          ${isEquipped && hasWeapon ? 'bg-red-900/50' : ''}
                        `}
                     >
                        <span className={`text-[8px] font-bold ${isSelected ? 'text-white' : 'text-gray-500'}`}>{w}</span>
                        {isEquipped && <div className="absolute top-1 right-1 w-2 h-2 bg-red-500 rounded-full shadow-[0_0_5px_red]"/>}
                     </div>
                   );
                })}
             </div>

             <div className="mt-4 h-32 border-2 border-gray-700 bg-black p-4">
                {props.selectedIndex < ALL_WEAPONS_SET_0.length ? (
                   <>
                      <div className="text-yellow-400 font-black italic text-lg mb-1">{ALL_WEAPONS_SET_0[props.selectedIndex]}</div>
                      <div className="text-gray-400 text-xs font-mono leading-tight">
                        {props.availableWeapons.includes(ALL_WEAPONS_SET_0[props.selectedIndex]) 
                          ? "EQUIP TO DESTROY." 
                          : "WEAPON NOT ACQUIRED."}
                      </div>
                   </>
                ) : (
                   <div className="text-gray-600 text-xs font-mono italic">SYSTEM PAUSED</div>
                )}
             </div>
          </div>

          {/* Menu Options */}
          <div className="w-1/3 flex flex-col gap-2 mt-12">
             <button 
               className={`text-left px-4 py-2 border-2 text-sm font-bold ${props.selectedIndex === ALL_WEAPONS_SET_0.length ? 'border-white bg-white text-black' : 'border-gray-600 text-gray-600'}`}
               onClick={props.onResume}
             >
               RESUME
             </button>
             <button 
               className={`text-left px-4 py-2 border-2 text-sm font-bold ${props.selectedIndex === ALL_WEAPONS_SET_0.length + 1 ? 'border-white bg-white text-black' : 'border-gray-600 text-gray-600'}`}
               onClick={props.onBossSelect}
             >
               EXIT STAGE
             </button>
             <button 
               className={`text-left px-4 py-2 border-2 text-sm font-bold ${props.selectedIndex === ALL_WEAPONS_SET_0.length + 2 ? 'border-white bg-white text-black' : 'border-gray-600 text-gray-600'}`}
               onClick={props.onQuitToMenu}
             >
               QUIT TO TITLE
             </button>

             {props.showCheats && (
                <div className="mt-8 pt-4 border-t border-gray-800 flex flex-col gap-1">
                   <div onClick={props.onToggleInvincibility} className={`text-[9px] cursor-pointer ${props.invincibilityEnabled ? 'text-green-500' : 'text-gray-700'}`}>GOD MODE</div>
                   <div onClick={props.onToggleInfiniteAmmo} className={`text-[9px] cursor-pointer ${props.infiniteAmmoEnabled ? 'text-green-500' : 'text-gray-700'}`}>INF AMMO</div>
                   <div onClick={props.onToggleInfinitePower} className={`text-[9px] cursor-pointer ${props.infinitePowerEnabled ? 'text-green-500' : 'text-gray-700'}`}>INF POWER</div>
                   <div onClick={props.onToggleJumpToBoss} className={`text-[9px] cursor-pointer ${props.jumpToBossEnabled ? 'text-green-500' : 'text-gray-700'}`}>BOSS WARP</div>
                </div>
             )}
          </div>
       </div>
     );
  }

  if (status === GameStatus.GAME_OVER) {
    return (
      <div className="absolute inset-0 bg-red-900/90 flex flex-col items-center justify-center z-50">
        <h1 className="text-6xl font-black text-black mb-4">YOU DIED</h1>
        <p className="text-xl text-white font-bold mb-8">PATHETIC DISPLAY</p>
        <div className="text-sm text-white animate-pulse">PRESS START TO RETRY</div>
      </div>
    );
  }

  if (status === GameStatus.VICTORY) {
    return (
      <div className="absolute inset-0 bg-white flex flex-col items-center justify-center z-50">
        <h1 className="text-6xl font-black text-black mb-4 italic">MISSION COMPLETE</h1>
        <p className="text-xl text-gray-800 font-bold mb-8">ALL TARGETS ELIMINATED</p>
        <div className="text-sm text-black animate-pulse">PRESS START</div>
      </div>
    );
  }

  return null;
};

export default Overlay;

import React, { useRef, useEffect } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Volcano, 
