  BOSS_CHARGE_DAMAGE, BOSS_UPPERCUT_DAMAGE, ENEMY_UPPERCUT_DAMAGE, ENEMY_HIT_COOLDOWN, FRICTION_DEFAULT, FRICTION_ICE_STAGE, FRICTION_ICE_STOP
} from '../constants';
import * as BossLogic from '../boss';
