interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, specialCharges: number, specialChargeTimer: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => void;
  onBossEncounter: () => void;
  onBossTransition: () => void;
  onBossDefeated: (stageId: string) => void;
  onBossDeath: () => void;
  onBossSelect: () => void;
  onGameOver: (victory: boolean) => void;
  onIntroComplete: () => void;
  onTogglePause: () => void;
  currentWeapon: WeaponType;
  initialAmmo: Record<WeaponType, number>;
  invincibilityEnabled: boolean;
  infiniteAmmoEnabled: boolean;
  infinitePowerEnabled: boolean;
  jumpToBossEnabled: boolean;
  bossTauntText: string;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  status, stageId, onPlayerUpdate, onBossEncounter, onBossTransition, 
  onBossDefeated, onBossDeath, onBossSelect, onGameOver, onIntroComplete, 
  onTogglePause, currentWeapon, initialAmmo, invincibilityEnabled, 
  infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled 
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Game State Refs
  const playerRef = useRef<Player>({
    id: 'player', pos: { x: 100, y: 0 }, vel: { x: 0, y: 0 }, width: 40, height: 60,
    health: 100, maxHealth: 100, type: 'player', isCharging: false, isUppercutting: false,
    isDucking: false, specialCharges: 2, specialChargeTimer: 0, chargeDuration: 0,
    isJumping: false, isGrounded: false, facing: 1, shootCooldown: 0, jumpPrepTimer: 0,
    landTimer: 0, invincibilityTimer: 0, pushbackTimer: 0, killSatisfactionTimer: 0,
    bossKillSatisfactionTimer: 0, hasUsedAirMove: false, jumpInputReleased: true,
    chargeInputReleased: true, currentWeapon: 'GUN', availableWeapons: ['GUN'],
    weaponAmmo: { ...initialAmmo }
  });

  const stateRef = useRef({
    frame: 0,
    camera: { x: 0, y: 0 },
    projectiles: [] as Projectile[],
    enemies: [] as Enemy[],
    particles: [] as Particle[],
    damageNumbers: [] as DamageNumber[],
    pickups: [] as Pickup[],
    bossVolcanoes: [] as Volcano[],
    bossVolcanoTelegraphs: [] as Volcano[],
    bossPoopTelegraphs: [] as any[],
    victorWallSide: 0,
    arenaLocked: false,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing',
    totalPullForceX: 0,
    tsunamiActive: false,
    tsunamiX: 0,
    tsunamiDir: 1,
    tsunamiStartX: 0,
    ernieVibrationTimer: 0,
    playerStunTimer: 0,
    playerVulgarityTimer: 0,
    playerLastVulgarity: "",
    bossVulgarityTimer: 0,
    bossLastVulgarity: "",
    voiceLineCooldown: 0
  });

  const keysRef = useRef<Record<string, boolean>>({});
  const mouseRef = useRef({ x: 0, y: 0, down: false });

  // Update ammo when prop changes
  useEffect(() => {
    playerRef.current.currentWeapon = currentWeapon;
    playerRef.current.weaponAmmo = { ...initialAmmo }; 
  }, [currentWeapon, initialAmmo]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keysRef.current[e.key.toLowerCase()] = true; keysRef.current['key' + e.key.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keysRef.current[e.key.toLowerCase()] = false; keysRef.current['key' + e.key.toLowerCase()] = false; };
    const handleMouseDown = () => { mouseRef.current.down = true; };
    const handleMouseUp = () => { mouseRef.current.down = false; };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  useEffect(() => {
    let animationFrameId: number;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Helpers
    const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX = 0, spread = 10) => {
        for(let i=0; i<count; i++) {
            stateRef.current.particles.push({
                pos: { x: pos.x, y: pos.y },
                vel: { x: baseVelX + (Math.random()-0.5)*spread, y: (Math.random()-0.5)*spread },
                life: 30 + Math.random() * 20,
                color: color,
                size: 3 + Math.random() * 5
            });
        }
    };

    const spawnDamageNumber = (pos: Vector2, value: number, isCritical = false) => {
        stateRef.current.damageNumbers.push({
            id: `dn-${Date.now()}-${Math.random()}`,
            value: Math.floor(value),
            pos: { x: pos.x, y: pos.y - 20 },
            vel: { x: (Math.random() - 0.5) * 2, y: -3 - Math.random() * 2 },
            life: 45, maxLife: 45, isCritical
        });
    };

    const spawnPickup = (pos: Vector2) => {
        if (Math.random() > 0.3) return;
        const type = Math.random() > 0.5 ? (Math.random() > 0.7 ? 'large_health' : 'small_health') : (Math.random() > 0.7 ? 'large_ammo' : 'small_ammo');
        stateRef.current.pickups.push({
            id: `pu-${Date.now()}`, pos: { ...pos }, vel: { x: (Math.random()-0.5)*4, y: -5 },
            width: 20, height: 20, type, life: 600
        });
    };

    const speakVulgarity = (type: any) => { /* Placeholder for sound/speech logic handled in App or globally */ };
    const playGunSound = (type: any) => { /* Placeholder */ };
    const setScreenShake = (duration: number) => { /* Placeholder */ };
    const spawnGlassShatter = (pos: Vector2) => spawnExplosion(pos, '#AEEEEE', 10);
    const spawnDeathShower = (pos: Vector2, facing: number) => spawnExplosion(pos, '#FF0000', 20);
    const spawnRockShatter = (pos: Vector2) => spawnExplosion(pos, '#8B4513', 8);
    const spawnBoulderShrapnel = (pos: Vector2, count: number, dir: number) => {
        for(let i=0; i<count; i++) {
            stateRef.current.projectiles.push({
                id: `shrapnel-${Date.now()}-${i}`,
                pos: { ...pos },
                vel: { x: dir * (4 + Math.random()*8), y: -5 - Math.random()*10 },
                width: 10, height: 10, health: 1, maxHealth: 1, type: 'projectile', damage: 10, owner: 'player', isShrapnel: true
            });
        }
    };
    const spawnPoopExplosion = (pos: Vector2, count: number) => spawnExplosion(pos, '#5D4037', count);
    const spawnPowderExplosion = (pos: Vector2, count: number) => spawnExplosion(pos, '#FFFFFF', count);
    const spawnMethExplosion = (pos: Vector2) => spawnExplosion(pos, '#00FFFF', 30);

    const weaponHelpers: WeaponHelpers = {
        addProjectile: (p) => stateRef.current.projectiles.push(p),
        addParticle: (p) => stateRef.current.particles.push(p),
        playGunSound,
        spawnExplosion,
        spawnDamageNumber,
        spawnGlassShatter,
        setScreenShake,
        triggerBossDeath: (boss, facing, wasWeakness) => bossHelpers.triggerBossDeath(boss, facing, wasWeakness, stageId, currentWeapon, stateRef.current, bossHelpers),
        spawnDeathShower,
        spawnPickup,
        speakVulgarity
    };

    const bossHelpers: BossHelpers = {
        addProjectile: (p) => stateRef.current.projectiles.push(p),
        addPoopTelegraph: (t) => stateRef.current.bossPoopTelegraphs.push(t),
        clearPoopTelegraphs: () => stateRef.current.bossPoopTelegraphs = [],
        speakVulgarity: (t) => speakVulgarity(t),
        addVolcano: (v) => stateRef.current.bossVolcanoes.push(v),
        addVolcanoTelegraph: (v) => stateRef.current.bossVolcanoTelegraphs.push(v),
        clearVolcanoTelegraphs: () => stateRef.current.bossVolcanoTelegraphs = [],
        setVictorWallSide: (s) => stateRef.current.victorWallSide = s,
        spawnDamageNumber,
        triggerBossDeath: (boss, facing, wasWeakness, sId, wpn, st, h) => {
             // Basic implementation triggering the callback
             onBossDeath();
        }
    };

    // Dummy blocks for environment
    const blocks: any[] = [
        { x: 0, y: 550, w: 10000, h: 50, type: 'ground' }, // Main Floor
        { x: -50, y: 0, w: 50, h: 600, type: 'wall' }, // Left Wall
        { x: BOSS_DOOR_X, y: 0, w: 40, h: 550, type: 'door' }, // Boss Door
        { x: 8000, y: 0, w: 50, h: 600, type: 'wall' } // Far Right Wall
    ];

    const gameLoop = () => {
        if (status === GameStatus.PAUSED) {
            animationFrameId = requestAnimationFrame(gameLoop);
            return;
        }

        const state = stateRef.current;
        const player = playerRef.current;
        const keys = keysRef;
        const mouse = mouseRef;

        // --- CORE GAME LOOP LOGIC FROM PROMPT ---
        const gamepads = navigator.getGamepads();
    const gp = gamepads[0];
    let padMoveX = 0, padMoveY = 0, padJump = false, padSpecial = false, padShoot = false;

    if (gp) {
      const DEADZONE = 0.2;
      if (Math.abs(gp.axes[0]) > DEADZONE) padMoveX = gp.axes[0];
      if (Math.abs(gp.axes[1]) > DEADZONE) padMoveY = gp.axes[1];
      if (gp.buttons[14]?.pressed) padMoveX = -1; 
      if (gp.buttons[15]?.pressed) padMoveX = 1;  
      if (gp.buttons[12]?.pressed) padMoveY = -1; 
      if (gp.buttons[13]?.pressed) padMoveY = 1;  
      padJump = gp.buttons[0]?.pressed; 
      padShoot = gp.buttons[2]?.pressed || gp.buttons[3]?.pressed; 
      padSpecial = gp.buttons[1]?.pressed; 
    }

    const km = keys.current, isStunned = state.playerStunTimer > 0, hasAmmo = (wpn: WeaponType) => wpn === 'GUN' || player.weaponAmmo[wpn] >= 1;
    const shootRequested = !isStunned && player.pushbackTimer <= 0 && (mouse.current.down || padShoot), 
          moveLeft = !isStunned && player.pushbackTimer <= 0 && (km['a'] || km['arrowleft'] || km['keya'] || padMoveX < -0.3), 
          moveRight = !isStunned && player.pushbackTimer <= 0 && (km['d'] || km['arrowright'] || km['keyd'] || padMoveX > 0.3), 
          moveDown = !isStunned && player.pushbackTimer <= 0 && (km['s'] || km['arrowdown'] || km['keys'] || padMoveY > 0.3), 
          moveUp = !isStunned && player.pushbackTimer <= 0 && (km['w'] || km['arrowup'] || km['keyw'] || padMoveY < -0.4),
          jumpRequested = !isStunned && player.pushbackTimer <= 0 && (km[' '] || km['space'] || km['z'] || km['keyz'] || km['j'] || km['keyj'] || padJump), 
          chargeRequested = !isStunned && player.pushbackTimer <= 0 && (km['shift'] || km['shiftleft'] || km['shiftright'] || km['c'] || km['keyc'] || padSpecial);

    if (state.playerStunTimer > 0) state.playerStunTimer--;
    if (state.playerVulgarityTimer > 0) { state.playerVulgarityTimer--; if (state.playerVulgarityTimer <= 0) state.playerLastVulgarity = ""; }
    if (state.bossVulgarityTimer > 0) { state.bossVulgarityTimer--; if (state.bossVulgarityTimer <= 0) state.bossLastVulgarity = ""; }
    if (state.voiceLineCooldown > 0) state.voiceLineCooldown--;
    if (player.invincibilityTimer > 0) player.invincibilityTimer--;
    if (player.killSatisfactionTimer > 0) player.killSatisfactionTimer--;
    if (player.bossKillSatisfactionTimer > 0) player.bossKillSatisfactionTimer--;
    if (player.pushbackTimer > 0) { player.pushbackTimer--; player.vel.x *= 0.9; }
    if (player.specialCharges < MAX_SPECIAL_CHARGES) { player.specialChargeTimer++; if (player.specialChargeTimer >= SPECIAL_CHARGE_REGEN_FRAMES) { player.specialCharges++; player.specialChargeTimer = 0; } }
    if (player.filthShieldTimer && player.filthShieldTimer > 0) player.filthShieldTimer--;
    if (!jumpRequested) player.jumpInputReleased = true;
    if (!chargeRequested) player.chargeInputReleased = true;

    const enemies = state.enemies;
    const projectiles = state.projectiles;

    if (currentWeapon === 'TASER' && shootRequested && hasAmmo('TASER')) {
      if (!player.isTasing) {
        WeaponLogic.fireWeapon(player, state, weaponHelpers, moveUp, moveDown, infiniteAmmoEnabled);
      }
      if (player.isTasing) {
        player.taserTimer = (player.taserTimer || 0) + 1;
        if (!infiniteAmmoEnabled && state.frame % TASER_AMMO_CONSUMPTION_RATE === 0) player.weaponAmmo['TASER'] -= 1;
        player.vel.x = 0;

        if (player.weaponAmmo['TASER'] <= 0) {
           player.isTasing = false;
           player.taserTargetId = null;
        }

        const target = (enemies.find(e => e.id === player.taserTargetId) || projectiles.find(p => p.id === player.taserTargetId)) as (Enemy | Projectile | undefined);
        if (target && (target.pos.x + target.width < state.camera.x || target.pos.x > state.camera.x + CANVAS_WIDTH)) {
            player.taserTargetId = null;
        }

        if (target && target.health > 0) {
          const dx = (target.pos.x + target.width/2) - (player.pos.x + player.width/2);
          const dy = (target.pos.y + target.height/2) - (player.pos.y + player.height/2);
          const dist = Math.sqrt(dx*dx + dy*dy);
          if (dist > TASER_RANGE + 100) {
            player.isTasing = false;
            player.taserTargetId = null;
          } else {
            if (target.type === 'boss') {
               const b = target as Enemy;
               if (!b.hitCooldown || b.hitCooldown <= 0) {
                  const dmg = BossLogic.getBossDamage(b, stageId, currentWeapon);
                  const isW = BossLogic.checkIsWeakness(stageId, currentWeapon);
                  b.health -= dmg;
                  b.hitCooldown = ENEMY_HIT_COOLDOWN;
                  spawnDamageNumber(b.pos, dmg, isW);
                  if (b.health <= 0) BossLogic.triggerBossDeath(b, player.facing, isW, stageId, currentWeapon, state, bossHelpers);
               }
            } else {
               target.isTased = true;
               if (state.frame % TASER_TICK_RATE === 0) {
                 target.health -= TASER_DOT_DAMAGE;
                 spawnDamageNumber(target.pos, TASER_DOT_DAMAGE);
                 if (target.health <= 0) {
                    if (target.type === 'enemy') {
                      const e = target as Enemy;
                      e.isBlownAway = true; 
                      e.vel = { x: (Math.random()-0.5)*10, y: -15 }; 
                      spawnDeathShower(e.pos, 0); 
                      spawnPickup(e.pos); 
                      speakVulgarity('taser_kill');
                    }
                    player.isTasing = false;
                    player.taserTargetId = null;
                 }
               }
               if (player.taserTimer! >= TASER_FIRE_THRESHOLD && !target.isOnFire) {
                 target.isOnFire = true;
                 playGunSound('ignite');
               }
            }
          }
        } else {
          if (player.taserTimer! > 30) {
             player.isTasing = false;
             player.taserTargetId = null;
          }
        }
      }
    } else {
      player.isTasing = false;
      player.taserTargetId = null;
      player.taserTimer = 0;
    }

    state.totalPullForceX = 0;

    projectiles.forEach(p => {
      if (p.health > 0 && p.isOnFire) {
        if (!p.fireTimer) p.fireTimer = 0; p.fireTimer++;
        if (p.fireTimer >= FIRE_TICK_RATE) {
          p.health -= FIRE_DOT_DAMAGE_HEAVY;
          spawnDamageNumber(p.pos, FIRE_DOT_DAMAGE_HEAVY);
          p.fireTimer = 0;
        }
        if (state.frame % 2 === 0) {
          state.particles.push({ pos: { x: p.pos.x + Math.random() * p.width, y: p.pos.y + Math.random() * p.height }, vel: { x: (Math.random()-0.5)*9, y: -Math.random()*15 }, life: 45, color: '#FF4500', size: 10 + Math.random()*12 });
        }
      }
      if (!player.isTasing || player.taserTargetId !== p.id) p.isTased = false;
    });

    enemies.forEach(e => {
      if (e.health > 0 && e.isOnFire) {
         if (!e.fireTimer) e.fireTimer = 0; e.fireTimer++;
         if (e.fireTimer >= FIRE_TICK_RATE) {
            const isBoss = e.type === 'boss';
            const dmg = isBoss ? FIRE_DOT_DAMAGE : FIRE_DOT_DAMAGE_HEAVY;
            e.health -= dmg;
            spawnDamageNumber(e.pos, dmg);
            e.fireTimer = 0;
            if (e.health <= 0) {
               if (isBoss) BossLogic.triggerBossDeath(e, 0, false, stageId, currentWeapon, state, bossHelpers);
               else { e.isBlownAway = true; e.vel = { x: (Math.random()-0.5)*10, y: -15 }; spawnDeathShower(e.pos, 0); spawnPickup(e.pos); speakVulgarity('flamethrower_kill'); }
            }
         }
         if (state.frame % 2 === 0) {
            const vx = (Math.random()-0.5)*9;
